'use strict';
const $=id=>document.getElementById(id);
let sales=null,busy=false,tradeDirty=false,pendingRedraft=false,signatureLogoUrl=null;
const el=(tag,text)=>{const item=document.createElement(tag);if(text!==undefined)item.textContent=text;return item;};
function notice(text,error=false){$('sales-status').textContent=text;$('sales-status').classList.toggle('error',error);$('sales-status').setAttribute('role',error?'alert':'status');if(error)$('sales-status').focus();}
function key(){const value=$('sales-gemini-key').value.trim();if(!/^[A-Za-z0-9._-]{20,512}$/.test(value))throw Error('본인의 Gemini API 키를 입력해 주세요.');return value;}
async function api(path,body,method){const response=await fetch('/api/'+path,{method:method||(body===undefined?'GET':'POST'),credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!response.ok){let detail;try{const data=await response.json();detail=data.message||data.detail?.message||data.error||data.detail;}catch{}throw Error(typeof detail==='string'?detail:'요청을 처리하지 못했습니다.');}return response.json();}
async function fileData(file){return {name:file.name,base64:await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);})};}
async function act(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(button=>button.disabled=true);notice('처리 중입니다. 잠시 기다려 주세요.');try{await fn();}catch(error){notice(error.message,true);}finally{busy=false;document.querySelectorAll('button').forEach(button=>button.disabled=false);updateGates();$('trade-export').disabled=!sales?.trade?.prepared?.ready_for_output_check||tradeDirty||!$('trade-final-confirm').checked;}}
function clearResult(){$('sales-result').hidden=true;$('sales-requests').replaceChildren();$('sales-documents').replaceChildren();$('sales-reply').value='';$('sales-subject').value='';$('sales-signature-preview').hidden=true;$('sales-eml').hidden=true;$('sales-sign-download-note').hidden=true;}
function renderProgress(progress){const panel=$('sales-progress'),steps=$('sales-progress-steps'),requests=$('sales-progress-requests');panel.hidden=!progress;steps.replaceChildren();requests.replaceChildren();if(!progress)return;const labels={queued:'작업 접수',composing:'받은 요청 분석 · 회신 구성',matching:'요청과 출처 연결',reviewing:'문장·요청 누락 독립 검수',assembled:'검수한 초안 조립 완료'};const events=progress.events||[];for(const [index,event] of events.entries()){const item=el('li',labels[event.stage]||'처리 단계');item.className=index===events.length-1?'current':'done';steps.append(item);}for(const item of progress.requests||[]){requests.append(el('p','요청: '+item.quote+' · 확인된 출처 '+item.source_count+'건'));}}
const SIGN_FIELDS={name:'sales-sign-name',title:'sales-sign-title',company:'sales-sign-company',phone:'sales-sign-phone',email:'sales-sign-email'};
function signatureValues(){const fields={};for(const [name,id] of Object.entries(SIGN_FIELDS)){const value=$(id).value.trim();if(value.length>160||/[\x00-\x1f]/.test(value))throw Error('서명은 각 항목당 160자 이하의 한 줄이어야 합니다.');fields[name]=value;}if(!fields.name||!fields.company||!(fields.phone||fields.email))throw Error('이름·회사명·전화 또는 이메일을 입력해 주세요.');if(fields.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.email))throw Error('이메일 주소를 확인해 주세요.');const logo=$('sales-sign-logo').files[0];if(logo&&(logo.size>2_000_000||!['image/png','image/jpeg'].includes(logo.type)||!/^.+\.(png|jpe?g)$/i.test(logo.name)))throw Error('로고는 2 MB 이하의 PNG/JPEG 파일만 사용할 수 있습니다.');return fields;}
function signedReply(){const original=sales?.result?.email||'';if(!$('sales-sign-confirm').checked)return original;const fields=signatureValues();const lines=[fields.name,fields.title,fields.company,fields.phone,fields.email].filter(Boolean).join('\n');return original.replace(/(?:\[Your name\]|\[보내는 사람 이름\])\s*$/,'').trimEnd()+'\n'+lines;}
function renderSignature(){const preview=$('sales-signature-preview'),eml=$('sales-eml'),note=$('sales-sign-download-note');preview.replaceChildren();const result=sales?.result;if(!result?.email){preview.hidden=eml.hidden=note.hidden=true;return;}if(!$('sales-sign-confirm').checked){$('sales-reply').value=result.email;preview.hidden=eml.hidden=note.hidden=true;$('sales-sign-status').textContent='입력값을 확인하고 체크하면 회신 끝에 서명이 자동으로 들어갑니다.';return;}let fields;try{fields=signatureValues();}catch(error){$('sales-sign-confirm').checked=false;$('sales-sign-status').textContent=error.message;renderSignature();return;}$('sales-reply').value=signedReply();preview.hidden=eml.hidden=note.hidden=false;preview.append(el('strong',fields.name));for(const name of ['title','company','phone','email'])if(fields[name])preview.append(el('div',fields[name]));if(signatureLogoUrl){const image=el('img');image.src=signatureLogoUrl;image.alt=fields.company+' 로고';preview.append(image);}$('sales-sign-status').textContent='확인한 서명이 회신 끝에 적용됐습니다. EML에서 로고 포함 여부를 확인해 주세요.';}
function updateFlow(){const active=!sales?'intake':!ready()?'evidence':sales.trade?.prepared?.ready_for_output_check?'trade':'writing';const order=['intake','evidence','writing','trade'];for(const link of document.querySelectorAll('[data-flow]')){const name=link.dataset.flow;link.classList.toggle('is-done',order.indexOf(name)<order.indexOf(active));if(name===active)link.setAttribute('aria-current','step');else link.removeAttribute('aria-current');}}
function render(data){sales=data;$('sales-evidence').hidden=false;$('sales-supplement').hidden=false;$('sales-files').replaceChildren();for(const file of data.intake.files){$('sales-files').append(el('p',file.filename+' · '+file.status+(file.reason?' · '+file.reason:'')));}renderConfirmations();renderTranscriptions();renderProgress(data.draft_progress);if(data.result){$('sales-language').value=data.result.language||'en';$('sales-tone').value=data.result.tone||'professional';renderResult(data.result);renderSignature();}else clearResult();renderTrade();updateGates();$('sales-supplement-status').textContent=(data.user_notes?.length||0)+'개 직접 입력 · '+data.intake.files.length+'개 첨부 자료';const failed=data.error&&data.operation==='sales_draft';$('sales-draft-error').hidden=!failed;$('sales-draft-error').textContent=failed?data.error.message+' 회신 작성 버튼으로 다시 시도할 수 있습니다.':'';if(data.error)notice(data.error.message||'작성을 완료하지 못했습니다.',true);else notice(data.status==='processing'?(data.operation==='sales_draft'?'Gemini가 요청별 답변을 작성하고 출처를 다시 대조하는 중입니다.':'원자료를 처리하는 중입니다.'):'작업 '+data.job_id+' · '+data.status);}
function renderTranscriptions(){const area=$('sales-transcriptions');area.replaceChildren();let count=0;for(const file of sales.intake.files){if(!file.manual_transcription_available)continue;for(const page of file.transcription_pages||[1]){const label=el('label',file.filename+' · '+page+'쪽 전체 원문 전사');const box=el('textarea');box.rows=5;box.dataset.sha=file.document_sha256;box.dataset.page=page;label.append(box);area.append(label);count++;}}$('sales-save-transcriptions').hidden=!count;$('sales-ocr').hidden=!sales.intake.files.some(file=>file.manual_transcription_available);}
function renderConfirmations(){const area=$('sales-confirmations');area.replaceChildren();let count=0;for(const source of sales.intake.sources){if(!source.requires_verification||sales.intake.confirmations.some(item=>item.source_id===source.source_id))continue;const details=el('details');details.append(el('summary',source.filename+' · '+(source.page||source.location)+' · '+source.source_id));details.append(el('pre',source.full_text||source.context_text||source.text));const label=el('label','원본 전체와 추출·전사문을 대조했음');label.className='check';const check=el('input');check.type='checkbox';check.dataset.receipt=source.source_id;check.dataset.fingerprint=source.verification_fingerprint;label.prepend(check);details.append(label);area.append(details);count++;}$('sales-confirm').hidden=!count;}
function ready(){const intake=sales?.intake;return intake&&intake.files.every(file=>file.status!=='deferred')&&intake.sources.every(source=>!source.requires_verification||intake.confirmations.some(item=>item.source_id===source.source_id));}
function updateGates(){updateFlow();const prepared=!!ready(),hasSources=!!sales?.intake.sources.length,names={proforma_invoice:'견적송장',commercial_invoice:'상업송장',packing_list:'포장명세서'},area=$('sales-documents-preview');area.replaceChildren();$('sales-draft').disabled=busy||!prepared;$('trade-propose').disabled=busy||!prepared||!hasSources;$('sales-supplement-submit').disabled=busy||!sales;$('sales-writing-gate').textContent=!sales?'1단계에서 받은 이메일을 등록해 주세요.':prepared?(hasSources?'원자료 준비 완료. 확인된 사실을 담은 회신을 작성할 수 있습니다.':'이메일만 등록됐습니다. 회사 사실은 단정하지 않는 일반 회신을 작성할 수 있습니다.'):'2단계에서 읽지 못한 파일과 미확인 원문을 대조해 주세요.';$('trade-gate').textContent=!sales||!hasSources?'회사 원자료를 올리면 거래 문서를 기입할 수 있습니다.':prepared?'원자료 준비 완료. 거래번호를 확인하고 입력칸별 후보를 찾으세요.':'2단계 원자료 확인을 마쳐야 거래 문서를 기입할 수 있습니다.';if(!sales)return;const documents=sales.requested_documents||[];area.append(el('p',documents.length?'받은 이메일에서 명시된 문서 요청: '+documents.map(id=>names[id]).join(', '):'견적송장·상업송장·포장명세서의 명시 요청은 감지되지 않았습니다. 다른 요청은 이메일 원문에서 직접 확인하세요.'));}
function renderResult(result){$('sales-result').hidden=false;const review=result.review||{};$('sales-review').classList.remove('error');$('sales-review').textContent=(review.coverage_check_required?'확인된 요청 범위의 회신 초안입니다. 이메일 전체 요청은 발송 전 한 번 더 대조해 주세요. ':'')+(review.message||'발송 전 내용을 확인해 주세요.')+' · 추가 확인 '+(review.pending_count||0)+'건';const list=$('sales-requests');list.replaceChildren();for(const item of result.requests){const card=el('article');card.append(el('h3',item.index+'. '+item.buyer_quote));const status=el('p',item.status==='draft'?'원자료 기반 답변':item.status==='general'?'이메일 기반 일반 회신':'추가 확인 필요');if(item.status==='needs_confirmation')status.className='pending';card.append(status);if(item.answer)card.append(el('p',item.answer));for(const proof of item.evidence){card.append(el('small',proof.source_id+' · '+proof.filename+' · '+(proof.origin==='user_input'?'담당자 직접 입력 · ':'')+(proof.location||proof.page||proof.sheet||'본문')+' · SHA '+proof.document_sha256));card.append(el('blockquote',proof.quote));}list.append(card);}$('sales-subject').value=result.subject||'';$('sales-reply').value=result.email||'';for(const id of ['sales-copy','sales-download','sales-evidence-download'])$(id).hidden=!result.email;const documents=$('sales-documents');documents.replaceChildren();if(result.documents?.length){const names={proforma_invoice:'견적송장',commercial_invoice:'상업송장',packing_list:'포장명세서'};documents.append(el('p','요청한 무역 문서: '+result.documents.map(id=>names[id]).join(', ')));const link=el('a','같은 원자료로 거래 문서 기입하기 →');link.href='#sales-trade';link.onclick=()=>{$('trade-workflow').value=result.documents[0];};documents.append(link);}}
function markTradeDirty(){tradeDirty=true;$('trade-export').disabled=true;$('trade-final-confirm').checked=false;$('trade-review').replaceChildren();}
function renderTrade(){const trade=sales?.trade,area=$('trade-fields');area.replaceChildren();$('trade-review').replaceChildren();$('trade-mapping').hidden=!trade;tradeDirty=false;$('trade-export').disabled=true;if(!trade)return;$('trade-workflow').value=trade.workflow;$('trade-transaction').value=trade.transaction;$('trade-rows').value=trade.rows;const proposals=Object.fromEntries(trade.proposal.fields.map(item=>[item.value_key,item]));$('trade-note').textContent='거래번호 '+trade.transaction+' · 원본 입력칸 '+trade.fields.length+'개. 일치하는 원문만 자동 제안합니다. 가격·조건·서명은 만들어 넣지 않습니다.';for(const field of trade.fields){const item=proposals[field.value_key];const label=el('label',field.label+(field.required?' · 필수':''));if(field.input_required){const input=el('input');input.dataset.tradeDirect=field.value_key;input.placeholder='담당자가 직접 확인·입력';input.value=trade.inputs?.direct_values?.[field.value_key]||'';input.addEventListener('input',markTradeDirty);label.append(input);}else{const select=el('select');select.dataset.tradeField=field.value_key;select.append(new Option(item.status==='missing'?'원문 없음 · 자료 보완 필요':'기입하지 않음',''));for(const [index,binding] of item.candidates.entries()){const source=sales.intake.sources.find(source=>source.source_id===binding.source_id);select.append(new Option(binding.quote+' · '+(source?.filename||'원자료')+' · '+(source?.location||''),String(index)));}const saved=trade.inputs?.source_bindings?.[field.value_key];if(saved){const index=item.candidates.findIndex(binding=>binding.source_id===saved.source_id&&binding.start===saved.start&&binding.quote===saved.quote);if(index>=0)select.value=String(index);}else if(item.candidates.length===1&&!trade.inputs)select.value='0';select.addEventListener('change',markTradeDirty);label.append(select);if(item.status==='ambiguous')label.append(el('small','후보가 여러 개입니다. 원문 위치를 확인해 선택하세요.'));}area.append(label);}$('trade-confirm').checked=false;$('trade-final-confirm').checked=false;if(trade.prepared){const review=$('trade-review');review.append(el('p',trade.prepared.ready_for_output_check?'수치·필수칸·출처 검수 통과 · 저장 후 입력 위치 검수는 다운로드 시 실행':'아직 출력할 수 없습니다. 부족한 항목을 보완하세요.'));if(trade.prepared.missing_fields.length)review.append(el('p','부족한 필수 항목: '+trade.prepared.missing_fields.join(', ')));for(const issue of trade.prepared.review.issues)review.append(el('p',(issue.field||issue.code)+' · '+issue.message));}}
async function settle(data){render(data);while(sales.status==='processing'){await new Promise(resolve=>setTimeout(resolve,2000));render(await api('sales/jobs/'+sales.job_id));}}
function download(name,data,type){const blob=new Blob([data],{type});const link=el('a');link.href=URL.createObjectURL(blob);link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),5000);}
$('sales-upload').onclick=()=>act(async()=>{const files=[...$('sales-sources').files],eml=$('buyer-eml').files[0],text=$('buyer-email').value.trim();if((!text&&!eml)||files.length>12)throw Error('받은 이메일을 입력하고 회사 원자료는 최대 12개까지 선택해 주세요.');if(new Set(files.map(file=>file.name.toLowerCase())).size!==files.length)throw Error('같은 파일명은 함께 올릴 수 없습니다.');const total=files.reduce((sum,file)=>sum+file.size,eml?.size||0);if(total>10*1024*1024)throw Error('한 번의 업로드는 10 MB 이하이어야 합니다.');const payload={email_text:text,email_eml:eml?await fileData(eml):undefined,sources:await Promise.all(files.map(fileData))};render(await api('sales/jobs',payload));sessionStorage.setItem('salesJobId',sales.job_id);notice(files.length?'이메일과 회사 자료를 등록했습니다. 원자료 상태를 확인해 주세요.':'이메일을 등록했습니다. 3단계에서 회신 초안을 작성해 주세요.');});
$('sales-ocr').onclick=()=>act(async()=>{if(!sales)throw Error('자료를 먼저 업로드해 주세요.');await settle(await api('sales/jobs/'+sales.job_id+'/intake',{auto_ocr:true,gemini_api_key:key()}));notice('읽은 원문을 원본 페이지와 대조하고 확인해 주세요.');});
$('sales-save-transcriptions').onclick=()=>act(async()=>{const transcriptions={};for(const input of document.querySelectorAll('[data-sha]')){if(!input.value.trim())throw Error('모든 대상 페이지의 전체 전사문을 입력해 주세요.');(transcriptions[input.dataset.sha]??=[]).push({page:Number(input.dataset.page),text:input.value});}render(await api('sales/jobs/'+sales.job_id+'/intake',{transcriptions}));notice('전사문을 등록했습니다. 원본 대조 확인이 필요합니다.');});
$('sales-confirm').onclick=()=>act(async()=>{const receipts=[...document.querySelectorAll('[data-receipt]')].filter(input=>input.checked).map(input=>({source_id:input.dataset.receipt,fingerprint:input.dataset.fingerprint}));if(!receipts.length)throw Error('원본을 대조한 항목을 선택해 주세요.');render(await api('sales/jobs/'+sales.job_id+'/intake',{receipts,confirmed:true}));if(pendingRedraft&&ready()){pendingRedraft=false;await settle(await api('sales/jobs/'+sales.job_id+'/draft',{language:$('sales-language').value,tone:$('sales-tone').value,gemini_api_key:key()}));}});
$('sales-draft').onclick=()=>act(async()=>{if(!ready())throw Error('모든 원자료를 읽고 미확인 스캔을 대조해 주세요.');await settle(await api('sales/jobs/'+sales.job_id+'/draft',{language:$('sales-language').value,tone:$('sales-tone').value,gemini_api_key:key()}));});
$('sales-supplement-submit').onclick=()=>act(async()=>{if(!sales)throw Error('이메일을 먼저 등록해 주세요.');const value=$('sales-supplement-text').value.trim(),files=[...$('sales-supplement-files').files];if(!value&&!files.length)throw Error('추가할 텍스트나 파일을 입력해 주세요.');const modelKey=key();const payload={text:value,sources:await Promise.all(files.map(fileData))};render(await api('sales/jobs/'+sales.job_id+'/supplement',payload));$('sales-supplement-text').value='';$('sales-supplement-files').value='';if(ready()){await settle(await api('sales/jobs/'+sales.job_id+'/draft',{language:$('sales-language').value,tone:$('sales-tone').value,gemini_api_key:modelKey}));}else{pendingRedraft=true;notice('추가 파일을 등록했습니다. 스캔·사진 원문 확인 후 초안을 업데이트합니다.');}});
$('sales-card-read').onclick=()=>act(async()=>{const card=$('sales-card-file').files[0];if(!card||card.size>5_000_000||!['image/png','image/jpeg'].includes(card.type))throw Error('5 MB 이하의 PNG/JPEG 명함 사진을 선택해 주세요.');$('sales-card-status').textContent='명함 사진에서 입력 후보를 읽고 있습니다.';const response=await api('sales/signature/read',{card:await fileData(card),gemini_api_key:key()});for(const [name,id] of Object.entries(SIGN_FIELDS))$(id).value=response.candidate[name]||'';$('sales-sign-confirm').checked=false;renderSignature();$('sales-card-status').textContent='명함 추출 후보를 채웠습니다. 원본과 각 항목을 대조하고 필요하면 수정해 주세요.';});
for(const id of Object.values(SIGN_FIELDS))$(id).addEventListener('input',()=>{$('sales-sign-confirm').checked=false;renderSignature();});
$('sales-sign-logo').addEventListener('change',()=>{if(signatureLogoUrl)URL.revokeObjectURL(signatureLogoUrl);signatureLogoUrl=null;const file=$('sales-sign-logo').files[0];if(file){if(file.size>2_000_000||!['image/png','image/jpeg'].includes(file.type)||!/^.+\.(png|jpe?g)$/i.test(file.name)){$('sales-sign-logo').value='';$('sales-sign-status').textContent='로고는 2 MB 이하의 PNG/JPEG만 사용할 수 있습니다.';}else signatureLogoUrl=URL.createObjectURL(file);}$('sales-sign-confirm').checked=false;renderSignature();});
$('sales-sign-confirm').addEventListener('change',()=>{if($('sales-sign-confirm').checked){try{signatureValues();}catch(error){$('sales-sign-confirm').checked=false;$('sales-sign-status').textContent=error.message;return;}}renderSignature();if($('sales-sign-confirm').checked&&!sales?.result)$('sales-sign-status').textContent='서명 확인 완료. 회신 초안 작성 후 자동으로 붙습니다.';});
$('sales-copy').onclick=()=>act(async()=>{if(!sales?.result?.email)throw Error('복사할 회신 초안이 없습니다.');await navigator.clipboard.writeText('Subject: '+sales.result.subject+'\n\n'+signedReply());notice('회신 텍스트를 복사했습니다. 로고는 EML 다운로드로 포함할 수 있습니다.');});
$('sales-download').onclick=()=>{if(sales?.result?.email)download('buyer_reply_draft.txt','Subject: '+sales.result.subject+'\n\n'+signedReply(),'text/plain;charset=utf-8');};
$('sales-eml').onclick=()=>act(async()=>{if(!sales?.result?.email||!$('sales-sign-confirm').checked)throw Error('서명을 확인한 회신 초안이 필요합니다.');const fields=signatureValues(),logo=$('sales-sign-logo').files[0];const response=await fetch('/api/sales/jobs/'+sales.job_id+'/signed-eml',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({fields,logo:logo?await fileData(logo):null,confirmed:true})});if(!response.ok){let detail;try{detail=await response.json();}catch{}throw Error(detail?.message||detail?.detail?.message||'서명 EML을 만들지 못했습니다.');}const file=await response.blob(),link=el('a');link.href=URL.createObjectURL(file);link.download='buyer_reply_signed.eml';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),5000);notice('서명과 로고를 포함한 미발송 EML을 다운로드했습니다. 발송 전 수신인·표시를 확인해 주세요.');});
$('sales-evidence-download').onclick=()=>{if(sales?.result?.email)download('buyer_reply_evidence.json',JSON.stringify(sales.result,null,2),'application/json;charset=utf-8');};
for(const id of ['trade-workflow','trade-transaction','trade-rows'])$(id).addEventListener('change',markTradeDirty);
$('trade-propose').onclick=()=>act(async()=>{if(!sales||!ready())throw Error('확인된 원자료를 먼저 준비해 주세요.');const transaction=$('trade-transaction').value.trim();if(!transaction)throw Error('원자료의 실제 거래번호를 입력해 주세요.');render(await api('sales/jobs/'+sales.job_id+'/trade/propose',{workflow:$('trade-workflow').value,transaction,rows:Number($('trade-rows').value)}));notice('입력칸별 원문 후보를 찾았습니다. 각 위치와 거래번호를 대조해 주세요.');});
$('trade-prepare').onclick=()=>act(async()=>{const trade=sales?.trade;if(!trade||!$('trade-confirm').checked)throw Error('원문 후보와 거래 조건을 직접 확인해 주세요.');const bindings={},direct={};for(const select of document.querySelectorAll('[data-trade-field]')){if(select.value==='')continue;const proposed=trade.proposal.fields.find(item=>item.value_key===select.dataset.tradeField);bindings[select.dataset.tradeField]=proposed.candidates[Number(select.value)];}for(const input of document.querySelectorAll('[data-trade-direct]')){if(input.value.trim())direct[input.dataset.tradeDirect]=input.value.trim();}render(await api('sales/jobs/'+sales.job_id+'/trade/prepare',{fingerprint:trade.fingerprint,source_bindings:bindings,direct_values:direct,confirmed:true}));notice(sales.trade.prepared.ready_for_output_check?'기입값 검수를 통과했습니다. 문서와 출처를 다시 확인해 주세요.':'부족한 항목·수치 관계가 있습니다. 원자료와 선택을 보완해 주세요.');});
$('trade-export').onclick=()=>act(async()=>{const prepared=sales?.trade?.prepared;if(!prepared?.ready_for_output_check||tradeDirty||!$('trade-final-confirm').checked)throw Error('현재 기입값과 출처를 확인해 주세요.');const response=await fetch('/api/sales/jobs/'+sales.job_id+'/trade/export',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({fingerprint:prepared.fingerprint,confirmed:true})});if(!response.ok){let data;try{data=await response.json();}catch{}throw Error(data?.message||data?.detail?.message||'출력 검수를 통과하지 못했습니다.');}const blob=await response.blob(),link=el('a');link.href=URL.createObjectURL(blob);link.download='trade_documents.zip';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),5000);notice('DOCX와 원문 출처·독립 검수 기록을 다운로드했습니다.');});
for(const id of ['buyer-email','buyer-eml','sales-sources'])$(id).addEventListener('change',()=>{if(sales){sales=null;pendingRedraft=false;clearResult();renderProgress(null);$('sales-evidence').hidden=true;$('sales-supplement').hidden=true;$('trade-mapping').hidden=true;$('sales-draft-error').hidden=true;sessionStorage.removeItem('salesJobId');updateGates();notice('입력이 바뀌었습니다. 다시 등록하면 새 작업을 만듭니다.');}});
for(const id of ['sales-language','sales-tone'])$(id).addEventListener('change',()=>{if(sales?.result){sales.result=null;clearResult();renderProgress(null);notice('언어 또는 톤이 바뀌었습니다. 같은 원자료로 회신을 다시 작성해 주세요.');}});
$('trade-final-confirm').addEventListener('change',()=>{$('trade-export').disabled=!$('trade-final-confirm').checked||!sales?.trade?.prepared?.ready_for_output_check||tradeDirty;});
Promise.all([api('me'),api('health')]).then(async([identity])=>{$('access-status').textContent=identity.access_mode==='guest'?'초대된 담당자 · 가입 불필요':'보호된 개인 작업실';const identifier=sessionStorage.getItem('salesJobId');if(identifier&&/^[0-9a-f]{32}$/.test(identifier)){try{render(await api('sales/jobs/'+identifier));return;}catch{sessionStorage.removeItem('salesJobId');}}notice('서버 연결 완료. 받은 이메일과 회사 자료를 넣어 주세요.');}).catch(error=>notice(error.message,true));
addEventListener('pagehide',()=>{$('sales-gemini-key').value='';if(signatureLogoUrl)URL.revokeObjectURL(signatureLogoUrl);});
updateGates();
